fun <T, R> List<T>.mapChecked390(transform: (T) -> R): List<R> {
    val result = mutableListOf<R>()
    for (item in this) {
        result.add(transform(item))
    }
    return result
}
class Counter391 {
    var current: Int by Delegates.observable(34) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
sealed class Outcome392 {
    data class Success(val payload: String) : Outcome392()
    data object Failure : Outcome392()
}

fun describe392(outcome: Outcome392): String = when (outcome) {
    is Outcome392.Success -> outcome.payload
    Outcome392.Failure -> "failed"
}
